#!/usr/bin/env python3
"""Verify chunk uploads with generated bytes on the local development stack."""
import uuid
from client import Client, check, compose, sql

alice, bob = Client('alice'), Client('bob')
part_size = 8 * 1024 * 1024
body = uuid.uuid4().bytes + bytes(range(256)) * (part_size // 128)
u = alice.create('chunk-test.png', body)
base = f"/api/v1/uploads/{u['upload_id']}"
Client().call('GET', base + '/parts', expected=401)
bob.call('GET', base + '/parts', expected=404)
bob.call('PUT', base + '/parts/0', b'x', expected=404)
bob.call('POST', base + '/complete', expected=404)
alice.call('PUT', base + '/parts/0', b'x', headers={'X-CSRF-Token': ''}, expected=403)
for number in ('-1', 'bad', '3'):
    alice.call('PUT', base + '/parts/' + number, b'x', expected=400)
alice.call('PUT', base + '/parts/0', b'x', expected=400)
alice.call('POST', base + '/complete', expected=409)
check('chunk authentication, CSRF, owner isolation, part index and size validation')

# Out-of-order writes, duplicate retries, and conflict rejection.
alice.call('PUT', base + '/parts/2', body[part_size * 2:])
alice.call('PUT', base + '/parts/0', body[:part_size])
alice.call('PUT', base + '/parts/0', body[:part_size])
alice.call('PUT', base + '/parts/0', bytes(part_size), expected=409)
status = alice.call('GET', base + '/parts')[2]
assert status['part_size'] == part_size
assert [p['part_number'] for p in status['parts']] == [0, 2]
assert all(set(p) == {'part_number', 'size_bytes'} for p in status['parts'])
alice.call('POST', base + '/complete', expected=409)
check('received part discovery, out-of-order upload, idempotent retry and mismatch rejection')

# Incomplete writes must not be advertised as received.
sql(f"UPDATE storage.upload_parts SET ready=false WHERE upload_id='{u['upload_id']}' AND part_number=0")
assert [p['part_number'] for p in alice.call('GET', base + '/parts')[2]['parts']] == [2]
alice.call('PUT', base + '/parts/0', body[:part_size])
alice.call('PUT', base + '/parts/1', body[part_size:part_size * 2])
# Tampering must fail authentication before any original is completed.
nonce = sql(f"SELECT encode(data_nonce,'hex') FROM storage.upload_parts WHERE upload_id='{u['upload_id']}' AND part_number=0")
sql(f"UPDATE storage.upload_parts SET data_nonce=decode(repeat('00',12),'hex') WHERE upload_id='{u['upload_id']}' AND part_number=0")
alice.call('POST', base + '/complete', expected=503)
sql(f"UPDATE storage.upload_parts SET data_nonce=decode('{nonce}','hex') WHERE upload_id='{u['upload_id']}' AND part_number=0")
alice.call('POST', base + '/complete')
alice.call('POST', base + '/complete')
alice.call('PUT', base + '/parts/0', b'x', expected=409)
asset = alice.asset(u)
content = f"/api/v1/assets/{u['asset_id']}/content"
assert alice.call('GET', content)[2] == body
assert alice.call('GET', content, headers={'Range': f'bytes={part_size-7}-{part_size+7}'}, expected=206)[2] == body[part_size-7:part_size+8]
assert sql(f"SELECT count(*) FROM storage.upload_parts WHERE upload_id='{u['upload_id']}'") == '0'
copy = bob.create('chunk-copy.png', body)
bob.put(copy, body)
assert bob.asset(copy)['blob_id'] == asset['blob_id']
bob.call('GET', content, expected=404)
check('incomplete write recovery, authenticated assembly, exact content, boundary Range, completion retry, part cleanup and cross-user deduplication')

# Empty and exact boundary uploads also work through the multipart API.
for data in (b'', body[:part_size]):
    session = alice.create('boundary.png', data)
    path = f"/api/v1/uploads/{session['upload_id']}"
    if data:
        alice.call('PUT', path + '/parts/0', data)
    alice.call('POST', path + '/complete')
    assert alice.call('GET', f"/api/v1/assets/{session['asset_id']}/content")[2] == data
check('empty and exact 8 MiB boundary assembly')

abandoned = alice.create('abandoned.png', b'x')
path = f"/api/v1/uploads/{abandoned['upload_id']}"
alice.call('PUT', path + '/parts/0', b'x')
sql(f"UPDATE storage.upload_parts SET created_at=now()-interval '26 hours' WHERE upload_id='{abandoned['upload_id']}'")
compose('exec', '-T', 'transfer', 'ocms', 'reconcile')
assert alice.call('GET', path + '/parts')[2]['parts'] == []
check('expired staging object collection')
print('All chunk upload integration checks passed.')
